import $api from "../http";
import { AxiosResponse } from "axios";


export default class AuthServices {
    static async register(username: string, email: string, password: string): Promise<AxiosResponse<{ data: string }>> {
        return $api.post('/register', {username, email, password});
    }

    static async login(username: string, password: string): Promise<AxiosResponse<{ data: string }>> {
        return $api.post<{ data: string }>('/login', {username, password});
    }
}
